import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { Attribute } from "./token.ts";
import { Node, nodeStack, insertionModeStack, reparentChildren, scopeMarker, scopeMarkerNode } from "./node.ts";

// Vectors are generated by ts/tools/gen-html-vectors (command "node") from Go's real
// html/node.go. Each scenario builds nodes, runs operations on them and on a nodeStack,
// and records the result of every operation (a panic flag, or the returned value) and
// the final state: the links of every node, the stack, a nested dump of the trees and
// the consistency of the links. Operation arguments are node indices, -1 for nil.
// "clone" appends the new node to the node list; "push" is the harness's append on the
// stack; a Go panic is a throw here.

interface NodeSpec {
  type: number;
  data: string;
  atom: number;
  ns: string;
  attrs: [string, string, string][] | null;
}

type Op = [string, ...number[]];

interface Scenario {
  nodes: NodeSpec[];
  ops: Op[];
  results: [boolean, unknown][];
  links: number[][];
  stack: number[];
  tree: unknown[] | null;
  consistent: boolean;
}

const vectors: { goVersion: string; scenarios: Scenario[] } = JSON.parse(
  readFileSync(new URL("./testdata/node_vectors.json", import.meta.url), "utf8")
);

// idxOf returns the index of n in nodes, -1 for nil, and -2 when n is not one of them.
function idxOf(nodes: Node[], n: Node | null): number {
  if (n === null) {
    return -1;
  }
  return nodes.indexOf(n);
}

// consistent is the same check as consistent in node_linkname.go / node_vectors.go.
function consistent(nodes: Node[]): boolean {
  for (const n of nodes) {
    if (n.FirstChild !== null && (n.FirstChild.PrevSibling !== null || n.FirstChild.Parent !== n)) {
      return false;
    }
    if (n.LastChild !== null && (n.LastChild.NextSibling !== null || n.LastChild.Parent !== n)) {
      return false;
    }
    if (n.NextSibling !== null && (n.NextSibling.PrevSibling !== n || n.NextSibling.Parent !== n.Parent)) {
      return false;
    }
    if (n.PrevSibling !== null && n.PrevSibling.NextSibling !== n) {
      return false;
    }
    if (
      n.Parent !== null &&
      ((n.PrevSibling === null) !== (n.Parent.FirstChild === n) ||
        (n.NextSibling === null) !== (n.Parent.LastChild === n))
    ) {
      return false;
    }
  }
  return true;
}

// dumpTree is the nested dump of n. A child already on the path or in the sibling list is
// recorded as a cycle, and the child list stops there.
function dumpTree(nodes: Node[], n: Node, seen: Set<Node>): unknown {
  seen.add(n);
  const attrs = n.Attr.map((a) => [a.Namespace, a.Key, a.Val]);
  const children: unknown[] = [];
  const visited = new Set<Node>();
  for (let c = n.FirstChild; c !== null; c = c.NextSibling) {
    if (visited.has(c) || seen.has(c)) {
      children.push({ cycle: idxOf(nodes, c) });
      break;
    }
    visited.add(c);
    children.push(dumpTree(nodes, c, seen));
  }
  seen.delete(n);
  // The keys are in the order of Go's JSON encoding of a map (sorted), so the dumps can be
  // compared as strings.
  return { a: attrs, c: children, d: n.Data, n: idxOf(nodes, n), t: n.Type };
}

function makeNode(spec: NodeSpec): Node {
  const n = new Node();
  n.Type = spec.type;
  n.Data = spec.data;
  n.DataAtom = spec.atom;
  n.Namespace = spec.ns;
  for (const [ns, k, v] of spec.attrs ?? []) {
    const a = new Attribute();
    a.Namespace = ns;
    a.Key = k;
    a.Val = v;
    n.Attr.push(a);
  }
  return n;
}

// runOp performs one operation and returns the value Go's harness recorded for it. A
// throw stands for a Go panic.
function runOp(op: Op, nodes: Node[], stack: nodeStack): unknown {
  const [name, a = 0, b = 0, c = 0] = op;
  switch (name) {
    case "append":
      nodes[a]!.AppendChild(nodes[b]!);
      return null;
    case "insertBefore":
      nodes[a]!.InsertBefore(nodes[b]!);
      return null;
    case "insertAfter":
      nodes[a]!.InsertAfter(nodes[b]!);
      return null;
    case "insertChildBefore": {
      const oldChild = c >= 0 ? nodes[c]! : null;
      nodes[a]!.InsertChildBefore(nodes[b]!, oldChild);
      return null;
    }
    case "removeChild":
      nodes[a]!.RemoveChild(nodes[b]!);
      return null;
    case "unlink":
      nodes[a]!.Unlink();
      return null;
    case "reparent":
      reparentChildren(nodes[a]!, nodes[b]!);
      return null;
    case "clone": {
      nodes.push(nodes[a]!.clone());
      return nodes.length - 1;
    }
    case "push":
      stack.items.push(nodes[a]!);
      return null;
    case "pop":
      return idxOf(nodes, stack.pop());
    case "top":
      return idxOf(nodes, stack.top());
    case "index":
      return stack.index(nodes[a]!);
    case "contains":
      return stack.contains(a);
    case "insert":
      stack.insert(a, nodes[b]!);
      return null;
    case "remove":
      stack.remove(nodes[a]!);
      return null;
  }
  throw new Error("unknown operation " + name);
}

function replay(sc: Scenario): { nodes: Node[]; stack: nodeStack; failures: string[] } {
  const nodes = sc.nodes.map(makeNode);
  const stack = new nodeStack();
  const failures: string[] = [];
  for (let i = 0; i < sc.ops.length; i++) {
    const op = sc.ops[i]!;
    const want = sc.results[i]!;
    let got: unknown = null;
    let panicked = false;
    try {
      got = runOp(op, nodes, stack);
    } catch {
      panicked = true;
    }
    if (panicked !== want[0]) {
      failures.push("op " + i + " " + JSON.stringify(op) + ": panic " + panicked + ", want " + want[0]);
    } else if (!panicked && JSON.stringify(got) !== JSON.stringify(want[1])) {
      failures.push("op " + i + " " + JSON.stringify(op) + ": got " + JSON.stringify(got) + ", want " + JSON.stringify(want[1]));
    }
  }
  return { nodes, stack, failures };
}

test("node vectors: scenarios replay with the same results and final state", () => {
  const all: string[] = [];
  vectors.scenarios.forEach((sc, s) => {
    const { nodes, stack, failures } = replay(sc);
    const fail = (msg: string): void => {
      all.push("scenario " + s + ": " + msg);
    };
    failures.forEach(fail);
    const links = nodes.map((n) => [
      idxOf(nodes, n.Parent),
      idxOf(nodes, n.FirstChild),
      idxOf(nodes, n.LastChild),
      idxOf(nodes, n.PrevSibling),
      idxOf(nodes, n.NextSibling),
    ]);
    if (JSON.stringify(links) !== JSON.stringify(sc.links)) {
      fail("links " + JSON.stringify(links) + " want " + JSON.stringify(sc.links));
    }
    const stk = stack.items.map((n) => idxOf(nodes, n));
    if (JSON.stringify(stk) !== JSON.stringify(sc.stack)) {
      fail("stack " + JSON.stringify(stk) + " want " + JSON.stringify(sc.stack));
    }
    const tree: unknown[] = [];
    for (const n of nodes) {
      if (n.Parent === null) {
        tree.push(dumpTree(nodes, n, new Set<Node>()));
      }
    }
    if (JSON.stringify(tree) !== JSON.stringify(sc.tree ?? [])) {
      fail("tree dump differs");
    }
    if (consistent(nodes) !== sc.consistent) {
      fail("consistent " + consistent(nodes) + " want " + sc.consistent);
    }
  });
  assert.deepEqual(all.slice(0, 20), [], all.length + " mismatches");
});

test("node vectors: the scenarios cover panics and clones", () => {
  // Coverage check: the vectors must contain the cases that the port asserts as throws.
  let panics = 0;
  let clones = 0;
  let stackNil = 0;
  for (const sc of vectors.scenarios) {
    for (let i = 0; i < sc.ops.length; i++) {
      if (sc.results[i]![0]) {
        panics++;
      }
      if (sc.ops[i]![0] === "clone" && !sc.results[i]![0]) {
        clones++;
      }
    }
    if (sc.stack.some((x) => x === -1)) {
      stackNil++;
    }
  }
  assert.ok(vectors.scenarios.length >= 200, "scenario count " + vectors.scenarios.length);
  assert.ok(panics > 100, "panicking operations " + panics);
  assert.ok(clones > 10, "clones " + clones);
  assert.ok(stackNil > 0, "scenarios that leave a nil stack element " + stackNil);
});

test("Node: AppendChild of an attached child and RemoveChild of a non-child throw (Go panics)", () => {
  const p = new Node();
  const c = new Node();
  p.AppendChild(c);
  assert.throws(() => p.AppendChild(c), /AppendChild called for an attached child Node/);
  const other = new Node();
  assert.throws(() => other.RemoveChild(c), /RemoveChild called for a non-child Node/);
  assert.throws(() => p.InsertChildBefore(c, null), /InsertChildBefore called for an attached child Node/);
});

test("nodeStack: pop on an empty stack throws, top returns null", () => {
  const s = new nodeStack();
  assert.equal(s.top(), null);
  assert.throws(() => s.pop());
});

test("insertionModeStack: pop and top (no Go vectors; insertionMode values are functions)", () => {
  const s = new insertionModeStack();
  assert.equal(s.top(), null);
  assert.throws(() => s.pop());
  const im = (): boolean => true;
  s.items.push(im);
  assert.equal(s.top(), im);
  assert.equal(s.pop(), im);
  assert.equal(s.top(), null);
});

test("scopeMarker is a node of the scope marker type", () => {
  assert.equal(scopeMarker.Type, scopeMarkerNode);
  assert.equal(scopeMarker.Parent, null);
});
